        try:
            o=json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            continue
        if isinstance(o,dict):
            out[name]={k:o.get(k) for k in ("state","task_id","attempt","retry_at","checkpoint","next_action","reason","type") if k in o}
